CREATE TABLE public.match_roles (pelada_id uuid NOT NULL REFERENCES public.matches(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES public.profiles(id),role text NOT NULL DEFAULT 'MESARIO' CHECK(role='MESARIO'),PRIMARY KEY(pelada_id,user_id));
GRANT SELECT ON public.match_roles TO authenticated; GRANT ALL ON public.match_roles TO service_role;
ALTER TABLE public.match_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "signed in role reads" ON public.match_roles FOR SELECT TO authenticated USING(true);
CREATE OR REPLACE FUNCTION public.can_operate_match(_match uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.matches m WHERE m.id=_match AND (m.creator_id=auth.uid() OR EXISTS(SELECT 1 FROM public.match_roles r WHERE r.pelada_id=COALESCE(m.pelada_id,m.id) AND r.user_id=auth.uid()))) $$;
CREATE OR REPLACE FUNCTION public.assign_match_mesario(_match uuid,_user uuid,_remove boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE root uuid; owner uuid; closed boolean; BEGIN SELECT COALESCE(pelada_id,id) INTO root FROM public.matches WHERE id=_match; SELECT creator_id,pelada_closed INTO owner,closed FROM public.matches WHERE id=root FOR UPDATE; IF auth.uid() IS NULL OR owner IS DISTINCT FROM auth.uid() OR closed THEN RAISE EXCEPTION 'Somente o criador de uma pelada aberta'; END IF; IF _remove THEN DELETE FROM public.match_roles WHERE pelada_id=root AND user_id=_user; RETURN; END IF; IF _user=owner THEN RAISE EXCEPTION 'O criador já é administrador'; END IF; IF NOT EXISTS(SELECT 1 FROM public.match_roles WHERE pelada_id=root AND user_id=_user) AND (SELECT count(*) FROM public.match_roles WHERE pelada_id=root)>=2 THEN RAISE EXCEPTION 'Máximo de dois mesários'; END IF; INSERT INTO public.match_roles(pelada_id,user_id) VALUES(root,_user) ON CONFLICT DO NOTHING; END $$;
ALTER TABLE public.matches ADD COLUMN clock_seconds integer NOT NULL DEFAULT 0 CHECK(clock_seconds>=0), ADD COLUMN clock_running_at timestamptz;
CREATE OR REPLACE FUNCTION public.operate_match_clock(_match uuid,_action text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE m public.matches; BEGIN SELECT * INTO m FROM public.matches WHERE id=_match FOR UPDATE; IF NOT public.can_operate_match(_match) OR m.pelada_closed OR m.status='finished' THEN RAISE EXCEPTION 'Operação não permitida'; END IF; IF _action='start' AND m.status='open' THEN UPDATE public.matches SET status='in_progress',started_at=now(),clock_running_at=now() WHERE id=_match; ELSIF _action='pause' AND m.status='in_progress' THEN UPDATE public.matches SET clock_seconds=clock_seconds+CASE WHEN clock_running_at IS NULL THEN 0 ELSE GREATEST(0,EXTRACT(epoch FROM now()-clock_running_at)::integer) END,clock_running_at=NULL WHERE id=_match; ELSIF _action='resume' AND m.status='in_progress' THEN UPDATE public.matches SET clock_running_at=COALESCE(clock_running_at,now()) WHERE id=_match; ELSE RAISE EXCEPTION 'Ação de cronômetro inválida'; END IF; END $$;
CREATE POLICY "operators add events" ON public.match_events FOR INSERT TO authenticated WITH CHECK(public.can_operate_match(match_id));
CREATE POLICY "operators undo events" ON public.match_events FOR DELETE TO authenticated USING(public.can_operate_match(match_id));
CREATE OR REPLACE FUNCTION public.apply_match_event() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ev public.match_events; delta integer; col text; state text; BEGIN IF TG_OP='INSERT' THEN ev:=NEW;delta:=1;ELSE ev:=OLD;delta:=-1;END IF; SELECT status INTO state FROM public.matches WHERE id=ev.match_id FOR UPDATE; IF NOT public.can_operate_match(ev.match_id) OR state<>'in_progress' THEN RAISE EXCEPTION 'Somente organizador ou mesário registra lances ao vivo';END IF; IF TG_OP='INSERT' AND NOT EXISTS(SELECT 1 FROM public.match_players WHERE match_id=ev.match_id AND player_id=ev.player_id AND team=ev.team AND presence='confirmed' AND team IN ('colete','sem_colete')) THEN RAISE EXCEPTION 'Atleta fora do campo';END IF; col:=CASE ev.type WHEN 'goal' THEN 'goals' WHEN 'assist' THEN 'assists' WHEN 'tackle' THEN 'tackles' WHEN 'shot_on_goal' THEN 'shots_on_goal' WHEN 'foul_suffered' THEN 'fouls_suffered' WHEN 'foul_committed' THEN 'fouls_committed' WHEN 'save' THEN CASE WHEN ev.difficult_save THEN 'difficult_saves' ELSE 'saves' END END; IF col IS NULL OR ev.minute<0 THEN RAISE EXCEPTION 'Lance inválido';END IF; EXECUTE format('UPDATE public.match_players SET %I=GREATEST(0,COALESCE(%I,0)+$1) WHERE match_id=$2 AND player_id=$3',col,col) USING delta,ev.match_id,ev.player_id; IF ev.type='goal' THEN IF ev.team='colete' THEN UPDATE public.matches SET score_team_a=GREATEST(0,COALESCE(score_team_a,0)+delta) WHERE id=ev.match_id;ELSE UPDATE public.matches SET score_team_b=GREATEST(0,COALESCE(score_team_b,0)+delta) WHERE id=ev.match_id;END IF;END IF; IF TG_OP='INSERT' THEN RETURN NEW;ELSE RETURN OLD;END IF;END $$;
CREATE TABLE public.tournaments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES public.profiles(id),name text NOT NULL CHECK(char_length(name) BETWEEN 3 AND 80),format text NOT NULL CHECK(format IN ('league','knockout')),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.tournaments TO authenticated; GRANT ALL ON public.tournaments TO service_role; ALTER TABLE public.tournaments ENABLE ROW LEVEL SECURITY; CREATE POLICY "members view tournaments" ON public.tournaments FOR SELECT TO authenticated USING(true);
CREATE TABLE public.sports_teams(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES public.profiles(id),tournament_id uuid NOT NULL REFERENCES public.tournaments(id) ON DELETE CASCADE,name text NOT NULL CHECK(char_length(name) BETWEEN 2 AND 60),crest_path text,seed integer NOT NULL CHECK(seed BETWEEN 1 AND 32),UNIQUE(tournament_id,seed));
GRANT SELECT ON public.sports_teams TO authenticated;GRANT ALL ON public.sports_teams TO service_role;ALTER TABLE public.sports_teams ENABLE ROW LEVEL SECURITY;CREATE POLICY "members view teams" ON public.sports_teams FOR SELECT TO authenticated USING(true);
CREATE TABLE public.team_roster(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),team_id uuid NOT NULL REFERENCES public.sports_teams(id) ON DELETE CASCADE,full_name text NOT NULL CHECK(char_length(full_name) BETWEEN 3 AND 100),shirt_number integer NOT NULL CHECK(shirt_number BETWEEN 0 AND 999),profile_id uuid REFERENCES public.profiles(id),UNIQUE(team_id,shirt_number));
GRANT SELECT ON public.team_roster TO authenticated;GRANT ALL ON public.team_roster TO service_role;ALTER TABLE public.team_roster ENABLE ROW LEVEL SECURITY;CREATE POLICY "members view rosters" ON public.team_roster FOR SELECT TO authenticated USING(true);
CREATE TABLE public.tournament_games(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tournament_id uuid NOT NULL REFERENCES public.tournaments(id) ON DELETE CASCADE,round integer NOT NULL CHECK(round BETWEEN 1 AND 64),position integer NOT NULL CHECK(position BETWEEN 1 AND 32),home_id uuid REFERENCES public.sports_teams(id),away_id uuid REFERENCES public.sports_teams(id),home_score integer CHECK(home_score>=0),away_score integer CHECK(away_score>=0),winner_id uuid REFERENCES public.sports_teams(id),played boolean NOT NULL DEFAULT false,next_round integer,next_position integer,UNIQUE(tournament_id,round,position));
GRANT SELECT ON public.tournament_games TO authenticated;GRANT ALL ON public.tournament_games TO service_role;ALTER TABLE public.tournament_games ENABLE ROW LEVEL SECURITY;CREATE POLICY "members view games" ON public.tournament_games FOR SELECT TO authenticated USING(true);
CREATE OR REPLACE FUNCTION public.create_tournament(_name text,_format text,_teams jsonb,_games jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE tid uuid;teamid uuid;team jsonb;athlete jsonb;g jsonb;idx integer:=0;ids uuid[];BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Entre para criar';END IF;IF jsonb_typeof(_teams)<>'array' OR jsonb_array_length(_teams) NOT BETWEEN 2 AND 32 OR jsonb_typeof(_games)<>'array' OR jsonb_array_length(_games)>1100 THEN RAISE EXCEPTION 'Campeonato inválido: 2 a 32 equipes';END IF; INSERT INTO public.tournaments(owner_id,name,format) VALUES(auth.uid(),_name,_format) RETURNING id INTO tid;FOR team IN SELECT value FROM jsonb_array_elements(_teams) LOOP idx:=idx+1;INSERT INTO public.sports_teams(owner_id,tournament_id,name,seed,crest_path) VALUES(auth.uid(),tid,team->>'name',idx,NULLIF(team->>'crest_path','')) RETURNING id INTO teamid;ids:=array_append(ids,teamid);IF jsonb_typeof(team->'roster')<>'array' OR jsonb_array_length(team->'roster')<1 THEN RAISE EXCEPTION 'Cadastre ao menos um atleta por time';END IF;FOR athlete IN SELECT value FROM jsonb_array_elements(team->'roster') LOOP INSERT INTO public.team_roster(team_id,full_name,shirt_number,profile_id) VALUES(teamid,athlete->>'name',(athlete->>'number')::integer,NULLIF(athlete->>'profile_id','')::uuid);END LOOP;END LOOP;FOR g IN SELECT value FROM jsonb_array_elements(_games) LOOP INSERT INTO public.tournament_games(tournament_id,round,position,home_id,away_id,next_round,next_position) VALUES(tid,(g->>'round')::integer,(g->>'position')::integer,ids[(g->>'home')::integer],ids[(g->>'away')::integer],(g->>'next_round')::integer,(g->>'next_position')::integer);END LOOP;RETURN tid;END $$;
CREATE OR REPLACE FUNCTION public.save_tournament_score(_game uuid,_home integer,_away integer,_winner uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE g public.tournament_games;t public.tournaments;w uuid;dest public.tournament_games;slot integer;BEGIN SELECT tournament_id INTO t.id FROM public.tournament_games WHERE id=_game;SELECT * INTO t FROM public.tournaments WHERE id=t.id FOR UPDATE;IF auth.uid() IS NULL OR t.owner_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Somente o organizador altera placares';END IF;SELECT * INTO g FROM public.tournament_games WHERE id=_game FOR UPDATE;IF g.home_id IS NULL OR g.away_id IS NULL OR _home<0 OR _away<0 OR _home IS NULL OR _away IS NULL THEN RAISE EXCEPTION 'Placar inválido';END IF;w:=CASE WHEN _home>_away THEN g.home_id WHEN _away>_home THEN g.away_id ELSE NULL END;IF t.format='knockout' THEN IF w IS NULL THEN IF _winner NOT IN (g.home_id,g.away_id) OR _winner IS NULL THEN RAISE EXCEPTION 'Indique vencedor dos pênaltis';END IF;w:=_winner;END IF;IF g.next_round IS NOT NULL THEN SELECT * INTO dest FROM public.tournament_games WHERE tournament_id=t.id AND round=g.next_round AND position=g.next_position FOR UPDATE;IF dest.played THEN RAISE EXCEPTION 'Próxima fase já jogada; placar anterior bloqueado';END IF;SELECT count(*) INTO slot FROM public.tournament_games WHERE tournament_id=t.id AND next_round=g.next_round AND next_position=g.next_position AND position<=g.position;IF slot=1 AND dest.home_id IS NULL OR slot=1 AND dest.home_id=g.winner_id THEN UPDATE public.tournament_games SET home_id=w WHERE id=dest.id;ELSE UPDATE public.tournament_games SET away_id=w WHERE id=dest.id;END IF;END IF;END IF;UPDATE public.tournament_games SET home_score=_home,away_score=_away,winner_id=w,played=true WHERE id=_game;END $$;
CREATE TABLE public.player_follows(follower_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,player_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,PRIMARY KEY(follower_id,player_id),CHECK(follower_id<>player_id));GRANT SELECT,INSERT,DELETE ON public.player_follows TO authenticated;GRANT ALL ON public.player_follows TO service_role;ALTER TABLE public.player_follows ENABLE ROW LEVEL SECURITY;CREATE POLICY "own follow reads" ON public.player_follows FOR SELECT TO authenticated USING(follower_id=auth.uid());CREATE POLICY "own follow writes" ON public.player_follows FOR INSERT TO authenticated WITH CHECK(follower_id=auth.uid());CREATE POLICY "own unfollow" ON public.player_follows FOR DELETE TO authenticated USING(follower_id=auth.uid());
CREATE TABLE public.team_follows(follower_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,team_id uuid NOT NULL REFERENCES public.sports_teams(id) ON DELETE CASCADE,PRIMARY KEY(follower_id,team_id));GRANT SELECT,INSERT,DELETE ON public.team_follows TO authenticated;GRANT ALL ON public.team_follows TO service_role;ALTER TABLE public.team_follows ENABLE ROW LEVEL SECURITY;CREATE POLICY "own team follow reads" ON public.team_follows FOR SELECT TO authenticated USING(follower_id=auth.uid());CREATE POLICY "own team follow writes" ON public.team_follows FOR INSERT TO authenticated WITH CHECK(follower_id=auth.uid());CREATE POLICY "own team unfollow" ON public.team_follows FOR DELETE TO authenticated USING(follower_id=auth.uid());
REVOKE ALL ON FUNCTION public.assign_match_mesario(uuid,uuid,boolean),public.operate_match_clock(uuid,text),public.create_tournament(text,text,jsonb,jsonb),public.save_tournament_score(uuid,integer,integer,uuid),public.can_operate_match(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.assign_match_mesario(uuid,uuid,boolean),public.operate_match_clock(uuid,text),public.create_tournament(text,text,jsonb,jsonb),public.save_tournament_score(uuid,integer,integer,uuid),public.can_operate_match(uuid) TO authenticated,service_role;